// astro.config.mjs
import { defineConfig } from "astro/config";
import node from "@astrojs/node";

export default defineConfig({
  output: "server",
  adapter: node({ mode: "standalone" }),
});

// src/pages/api/menu.json.ts
import type { APIRoute } from "astro";

export const GET: APIRoute = () => {
  const menu = ["Bakso", "Soto"];
  return Response.json(menu);
};

import { defineMiddleware } from "astro:middleware";

export const onRequest = defineMiddleware(
  (context, next) => {
    const id = context.cookies.get("sesi")?.value;
    if (!id) return context.redirect("/masuk");
    context.locals.sesi = id;
    return next();
  });

import { defineAction } from "astro:actions";
import { z } from "astro/zod";

export const server = {
  pesan: defineAction({
    input: z.object({ menu: z.string() }),
    handler: async ({ menu }) => `Pesan ${menu}`,
  }),
};
